```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, min(time) t0, max(time) t1 FROM abnormal_traces WHERE service_name='rate' GROUP BY 1,2,3", "claim": "Rate emitted only 3 server spans, all within 0.15s of the abnormal window start at 11:49:38, then stopped."},
        {"kind": "log", "sql": "SELECT service_name, level, count(*) n, min(time) t0, max(time) t1 FROM abnormal_logs WHERE service_name='rate' GROUP BY 1,2 UNION ALL SELECT service_name, level, count(*), min(time), max(time) FROM normal_logs WHERE service_name='rate' GROUP BY 1,2", "claim": "Rate logged 3 INFO lines in the abnormal period versus 766 in the five normal minutes."},
        {"kind": "metric", "sql": "SELECT 'normal' p, avg(value) v FROM normal_metrics WHERE service_name='rate' AND metric='container.cpu.usage' UNION ALL SELECT 'abnormal', avg(value) FROM abnormal_metrics WHERE service_name='rate' AND metric='container.cpu.usage'", "claim": "Rate container CPU usage fell from about 0.005 to 0.0006 while its pod kept reporting metrics."},
        {"kind": "metric", "sql": "SELECT metric, count(*) n FROM abnormal_metrics WHERE service_name='rate' AND metric IN ('k8s.container.restarts','k8s.pod.uptime') GROUP BY 1", "claim": "No restart or uptime-reset metric exists for rate, so the instance did not restart and stayed gone."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2,3", "claim": "All 628 search calls to rate.Rate/GetRates returned Error in about 0.015 ms p50 against roughly 2 ms normally."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE message='Failed to get rates from rate service' GROUP BY 1,2,3", "claim": "Search logged 839 errors 'Failed to get rates from rate service' during the incident."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2,3,4", "claim": "Frontend's search.Search/Nearby client calls all errored, and every HTTP /hotels request returned 500."}
      ]
    }
  ]
}
